from pllib import *
import sys
H = int(sys.argv[1]) if len(sys.argv) > 1 else 1900
b = Board('Planning_Rules', 'Rules', 1280, H, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}.mono{font-family:'JetBrains Mono',monospace;font-size:12px}.tbl{display:grid;gap:8px 12px;font-size:13px;line-height:20px;color:#334155;align-items:center}</style>'''
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
def sw(st, t):
    col, soft = STAT[st]
    return f'<span style="display:inline-block;width:46px;height:16px;box-sizing:border-box;border:2px solid {col};border-radius:6px;background:{soft}"></span><span><b>{t}</b></span>'
stat = ''.join(sw(s, t) + '' for s, t in [('done', 'Done: green bar with a check'), ('doing', 'In progress: blue, filled to the progress'), ('plan', 'Planned: grey, empty'), ('blocked', 'Blocked: rose, with a short reason')])
cards = [
 card('What it covers', ul('Four types that plan work and people: <b>Gantt</b> (tasks over time), <b>Org chart</b> (who reports to whom), <b>Mind map</b> (areas of one topic), <b>Kanban and Roadmap</b> (work by state, or by quarter).', 'They share a status palette, a way of drawing people, and the same animation rule.')),
 card('Status colours', f'<div class="tbl" style="grid-template-columns:60px 1fr">{stat}</div>' + ul('Status is always colour and a second cue: a check, a fill, a dashed border. Never colour alone.')),
 card('People', ul('A person is a circle with initials, 26 px on a Gantt row, 28 px on a card, 40 px on an org card.', 'The tint belongs to the person or team and stays the same in every diagram: Minh is blue, Courier operations is teal.', 'A role is a noun phrase, not a sentence: <i>Mobile developer</i>.')),
 card('Gantt: axis and rows', ul('Weeks 88 px wide, a month header above them. A label column 300 px wide on the left.', 'Rows 52 px high. A phase is a grey band row with a bold name; its tasks follow.', 'A bar is 26 px high with 8 px of space each side of its week. The owner circle sits in the label column.', 'About 15 rows per page. Longer: one Gantt per phase.')),
 card('Gantt: milestones, today, links', ul('A milestone is an amber diamond on its own row, on the date line where it falls.', 'The <b>today</b> line is red and dashed, with a red pill under it.', 'A dependency is a thin ink arrow from the end of a task to the start of the next: finish to start. It leaves 8 px right of the bar.', 'The <b>critical path</b> is the one chain of tasks that sets the end date. It is blue, thick and animated, one per chart.')),
 card('Org chart', ul('A card per person: 210 × 78 plain, 232 × 110 illustrated. Levels 240 to 270 px apart, cards 250 px apart in a row.', 'A solid bus line runs from a manager down to a bar, then to each report. A dashed slate line with a pill is a working link without reporting.', 'An open role is a dashed card, faded, named by its title and marked <i>Open role</i>.', 'Four levels fit a page. A larger organisation gets one chart per department.')),
 card('Mind map', ul('One topic in a card at the centre with a large icon. Six branches fit best, three each side, 300 px apart.', 'A branch is a solid colour pill with a round icon. Its leaves are white cards with a colour bar, a small icon and a phrase of at most four words, four per branch.', 'Curved lines, 8 px at the centre and 4 px at the leaves. Colour follows the branch.', 'Up to four levels: branch, group, idea, detail. Markers on an idea: P1 and P2 for priority, a check for done, an owner circle, and +N when more ideas are hidden. A dashed violet arc with a pill links two ideas on different branches.', 'No order is implied and nothing animates. A plain version (tinted pills, underlined leaves) is kept for quick maps.')),
 card('Kanban', ul('Columns 360 px wide, in the order work moves: Backlog, In progress, In review, Done.', 'A card is 100 px high: title, kind tag (Feature, Bug, Chore) and an owner circle. A done card is struck through.', 'A column with a limit shows <span class="mono">3 / 3</span>. The pill turns red when the column is full.', 'Cards are listed in priority order, top to bottom.')),
 card('Roadmap', ul('Themes in rows, each with an icon card. Columns are <i>Now</i>, <i>Next</i>, <i>Later</i> with their dates.', 'A solid card is committed. A dashed card is being explored and may change or disappear.', 'The one dependency that decides the order is a blue animated arrow, with a note below the chart.', 'No exact dates in a roadmap: dates belong to a Gantt.')),
 card('Plain and illustrated', ul('<b>Org chart</b> and <b>Mind map</b> have both: plain, or cards with large icons. <b>Roadmap</b> uses lane icons from the detailed set.', '<b>Gantt and Kanban</b> are plain only. Large icons would add noise to dense charts.', 'Rules stay the same in both styles.')),
 card('Animation', ul('Only the critical path of a Gantt and the dependency arrow of a roadmap animate: blue, thick, fast. One per chart.', 'Everything else is static. Off when the viewer prefers reduced motion.', 'In draw.io each line has its own flow animation (flowAnimation=1) and its own duration: main route 500, event stream 1500. Checked in the draw.io viewer; SVG export not yet tested.')),
 card('What a plugin can rely on', ul('A task is: id, name, owner, start, end, status, progress (0 to 1), depends on. A milestone is: name, date.', 'A person is: name, role, manager, team, open (true or false). A mind map is: topic, branches, leaves. A card is: title, kind, owner, column.', 'A roadmap item is: title, theme, horizon (now, next, later), committed (true or false).', 'Layout comes from dates, reporting lines and columns. The plugin computes positions and routes lines.', 'Anything not covered is left to the diagram author.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">Planning · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">The conventions for Gantt, org chart, mind map, Kanban and roadmap, and what a plugin can rely on. The examples show each type once.</div></div>{grid}</div>')
print(save4(b))
